  practice: { label: '5 நிமிடம் மணம், மௌனம்', detail: 'ஒரு ஊதுபத்தி அல்லது விளக்கேற்றி, ஐந்து நிமிடம் அதன் மணத்தில் மௌனமாக இருங்கள்.', route: '/practice/dhyanam', minutes: 5 },
